        public display SysInfoLogStr logText(Common _staging)
        {
            #define.NewLine('\n')
            ;
            DMFStagingValidationLog stagingValidationLog;
            str                     logStr;
            SysInfoLogStr           logText;
            FieldId                 execFieldId,
                                    defGroupFieldId;

            //execFieldId = fieldName2Id(_staging.TableId,identifierStr(ExecutionId));
            //defGroupFieldId = fieldName2Id(_staging.TableId,identifierStr(DefinitionGroup));

            while select ErrorMessage, RecId from stagingValidationLog
                order by stagingValidationLog.RecId desc
                where stagingValidationLog.DefinitionGroupName == METLedgerJournalEntityInquiryView.DefinitionGroup
                   && stagingValidationLog.ExecutionId == METLedgerJournalEntityInquiryView.ExecutionId
                   && stagingValidationLog.StagingRecId == METLedgerJournalEntityInquiryView.StagingRecId
                   && stagingValidationLog.EntityName   == METLedgerJournalEntityInquiryView.Entity
            {
                logStr = #NewLine + stagingValidationLog.ErrorMessage;

                logText += logStr;
            }
            if(!logText)
            {
                logText = "@MET:LogTxtErr";
            }
            return logText;
        }

